    macro_indicator_us_cpi_yoy: "美国 CPI 同比",
    macro_indicator_us_10y_yield: "美国10年期国债收益率",
    macro_indicator_us_core_cpi_mom: "美国核心 CPI 环比",
    macro_indicator_us_ppi: "美国 PPI 同比",
    macro_indicator_us_industrial_production: "美国工业产出同比",
    macro_indicator_us_non_farm: "美国非农就业",
    macro_indicator_us_unemployment: "美国失业率",
    macro_tip_cn_cpi_yoy: "【消费者物价指数同比】衡量居民消费品价格变动。CPI温和上涨(2-3%)利于消费和盈利增长；过高引发紧缩预期压制估值；过低甚至通缩则反映需求疲软。",
    macro_tip_cn_ppi_yoy: "【生产者价格指数同比】衡量出厂价格变动，领先CPI约1-2个季度。PPI上行预示企业成本压力增大，中下游利润承压；PPI下行则利好制造业毛利修复。",
    macro_tip_cn_pmi: "【制造业采购经理指数】50为荣枯线。PMI>50表示扩张，<50收缩。PMI持续走强通常对应企业盈利改善和周期股机会；跌破50则需警惕经济放缓风险。",
    macro_tip_cn_m2_yoy: "【广义货币供应量同比】反映市场流动性充裕程度。M2增速高于名义GDP增速意味着宽松环境，利好风险资产；M2持续下行则暗示流动性收紧，对高估值板块形成压力。",
    macro_tip_cn_new_credit: "【新增人民币贷款】反映银行体系向实体注入的信用规模。社融放量+信贷扩张=宽信用周期，利好金融、地产等利率敏感型行业；信贷萎缩则信号偏空。",
    macro_tip_cn_social_financing: "【社会融资规模存量】综合反映实体经济从金融体系获得的全部资金。社融增速回升是经济企稳的先行指标；增速下滑则预示信用周期转弱。",
    macro_tip_cn_10y_yield: "【10年期国债收益率】无风险利率锚定。收益率下行=债牛+利好成长股DCF估值；收益率快速上行则压制高估值板块，且可能触发外资流出新兴市场。",
    macro_tip_cn_lpr_1y: "【1年期LPR报价】短期贷款基准利率。LPR下调直接降低企业融资成本，刺激投资和消费；上调则收紧流动性预期。",
    macro_tip_cn_lpr_5y: "【5年期LPR报价】房贷和中长期贷款基准。5年期LPR下调最直接影响地产链和基建板块；是观察货币政策松紧的核心窗口。",
    macro_tip_cn_margin_sh: "【上交所融资余额】反映A股杠杆资金情绪。融资余额持续攀升=市场风险偏好上升，往往伴随量价齐升；快速回落则预警回调或踩踏风险。",
    macro_tip_cn_margin_sz: "【深交所融资余额】同上交所，侧重中小盘/科技成长股的杠杆情绪。深市融资变化对创业板指有较强领先性。",
    macro_tip_us_cpi_yoy: "【美国CPI同比】全球通胀风向标。美国CPI超预期→美联储鹰派加息→美元走强→新兴市场资本外流+美债收益率上行→全球风险资产承压。",
    macro_tip_us_10y_yield: "【美国10年期国债收益率】全球资产定价之锚。美债收益率上行压制全球成长股估值，尤其对纳斯达克和港股科技股冲击明显；下行则释放估值空间。",
    macro_tip_us_core_cpi_mom: "【美国核心CPI环比】剔除食品能源后的通胀核心项。核心CPI是美联储决策的最重要参考之一，环比超预期会强化加息路径预期。",
    macro_tip_us_ppi: "【美国PPI同比】生产端通胀指标。PPI向CPI传导约3-6个月，可研判未来通胀走势。PPI超预期上行增加\u201c滞胀\u201d担忧。",
    macro_tip_us_industrial_production: "【工业产出同比】衡量美国制造业景气度。产出强劲=经济基本面健康，支撑美股盈利预期；大幅下滑则预示衰退风险，利好防御性板块。",
    macro_tip_us_non_farm: "【非农就业人数】每月最重要经济数据之一。非农超预期→就业市场火热→工资上涨→通胀粘性→美联储维持高利率更久 (Higher for Longer)。",
    macro_tip_us_unemployment: "【失业率】反向指标：失业率低=劳动力市场紧张=工资通胀压力大。失业率低于4%时美联储难以降息；突破4.5%以上则衰退概率显著升高。",
    macro_bench_cn_cpi_yoy: "目标区间 2%~3%",
